import static org.junit.Assert.*;

public class Partial_with_TriageGen1Test {

    @Test
    public void testWith_NullFieldTypeThrowsException() {
        Partial partial = new Partial(ISOChronology.getInstanceUTC());
        try {
            partial.with(null, 10);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("The field type must not be null", e.getMessage());
        }
    }

    @Test
    public void testWith_ExistingFieldSameValueReturnsThis() {
        DateTimeFieldType yearType = DateTimeTypes.year();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2023}, ISOChronology.getInstanceUTC());

        Partial result = partial.with(yearType, 2023);

        assertSame("Should return the same instance if value is unchanged", partial, result);
    }

    @Test
    public void testWith_ExistingFieldDifferentValueUpdatesValue() {
        DateTimeFieldType yearType = DateTimeTypes.year();
        DateTimeFieldType monthType = DateTimeTypes.monthOfYear();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType, monthType}, new int[]{2023, 1}, ISOChronology.getInstanceUTC());

        Partial result = partial.with(yearType, 2024);

        assertEquals(2, result.size());
        assertEquals(2024, result.getValue(0));
        assertEquals(1, result.getValue(1));
    }

    @Test
    public void testWith_AddNewFieldAtBeginning() {
        // Year has a larger duration than Month, so Month should be inserted before Year if we follow the logic 
        // of the loop: if (unitField.compareTo(loopUnitField) > 0) break;
        // Actually, the logic is designed to keep largest-smallest order (descending duration).
        // Let's test adding a field that should go to the front.

        DateTimeFieldType yearType = DateTimeTypes.year();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2023}, ISOChronology.getInstanceUTC());

        // Adding Millisecond (very small unit)
        DateTimeFieldType milliType = DateTimeTypes.millisecondOfSecond();
        Partial result = partial.with(milliType, 500);

        assertEquals(2, result.size());
        // Depending on the comparison logic in the code:
        // Year unit field vs Milli unit field -> Year is larger.
        // The loop breaks when unitField (new) > loopUnitField (existing).
        // So if we add Millisecond, it's smaller than Year, so it continues.
        // If we add Year, and it's larger than existing, it breaks.

        // Let's verify the content regardless of exact index order
        boolean foundYear = false;
        boolean foundMilli = false;
        for (int i = 0; i < result.size(); i++) {
            if (result.getFieldType(i).equals(yearType)) {
                assertEquals(2023, result.getValue(i));
                foundYear = true;
            }
            if (result.getFieldType(i).equals(milliType)) {
                assertEquals(500, result.getValue(i));
                foundMilli = true;
            }
        }
        assertTrue(foundYear && foundMilli);
    }

    @Test
    public void testWith_AddNewFieldInMiddleWithRangeComparison() {
        // This test targets the 'else if (compare == 0)' branch for range duration
        // We need two field types with same duration but different range durations.
        // In Joda, most fields have different durations. 
        // However, we can simulate the logic via the provided field types.

        DateTimeFieldType type1 = DateTimeTypes.year();
        DateTimeFieldType type2 = DateTimeTypes.century(); 
        // Century is larger than Year.

        Partial partial = new Partial(new DateTimeFieldType[]{type1}, new int[]{2023}, ISOChronology.getInstanceUTC());
        Partial result = partial.with(type2, 21);

        assertEquals(2, result.size());
        boolean foundCentury = false;
        boolean foundYear = false;
        for (int i = 0; i < result.size(); i++) {
            if (result.getFieldType(i).equals(type2)) {
                assertEquals(21, result.getValue(i));
                foundCentury = true;
            } else if (result.getFieldType(i).equals(type1)) {
                assertEquals(2023, result.getValue(i));
                foundYear = true;
            }
        }
        assertTrue(foundCentury && foundYear);
    }

    @Test
    public void testWith_AddNewFieldAtEnd() {
        DateTimeFieldType yearType = DateTimeTypes.year();
        DateTimeFieldType monthType = DateTimeTypes.monthOfYear();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2023}, ISOChronology.getInstanceUTC());

        // Month is smaller than Year, so loop continues until i == iTypes.length
        Partial result = partial.with(monthType, 12);

        assertEquals(2, result.size());
        assertEquals(2023, result.getValue(0));
        assertEquals(12, result.getValue(1));
    }
}
